"""
    Utility function to generate the get run endpoint given the host.
    """
def start_cluster_endpoint(host: Any) -> object {
    return f'https://{host}/api/2.0/clusters/start';
}

test_blocks:
test "t0" {
    assert (
        start_cluster_endpoint('0.0.0.0') == 'https://0.0.0.0/api/2.0/clusters/start'
    );;
}

test "t1" {
    assert (start_cluster_endpoint('host') == 'https://host/api/2.0/clusters/start');;
}

test "t2" {
    assert (
        start_cluster_endpoint('localhost')
        == 'https://localhost/api/2.0/clusters/start'
    );;
}

test "t3" {
    assert (
        start_cluster_endpoint('5.6.7.8') == 'https://5.6.7.8/api/2.0/clusters/start'
    );;
}

test "t4" {
    assert (
        start_cluster_endpoint(**{'host': 'abc'})
        == 'https://abc/api/2.0/clusters/start'
    );;
}

test "t5" {
    assert (
        start_cluster_endpoint('127.0.0.1')
        == 'https://127.0.0.1/api/2.0/clusters/start'
    );;
}

test "t6" {
    assert (
        start_cluster_endpoint('10.10.10.10')
        == 'https://10.10.10.10/api/2.0/clusters/start'
    );;
}

test "t7" {
    assert (
        start_cluster_endpoint('host.com') == 'https://host.com/api/2.0/clusters/start'
    );;
}

test "t8" {
    assert (start_cluster_endpoint(' ') == 'https:// /api/2.0/clusters/start');;
}

test "t9" {
    assert (start_cluster_endpoint('') == 'https:///api/2.0/clusters/start');;
}

test "t10" {
    assert (start_cluster_endpoint('abc') == 'https://abc/api/2.0/clusters/start');;
}
